class Account extends DataClass implements Insertable<Account> {
  final int id;
  final int ledgerId;
  final String name;
  final String type;
  final String currency;
  final double initialBalance;
  final DateTime? createdAt;
  final DateTime? updatedAt;
  final int sortOrder;
  final double? creditLimit;
  final int? billingDay;
  final int? paymentDueDay;
  final String? bankName;
  final String? cardLastFour;
  final String? note;
  final String? syncId;

  /// 隐藏:true 时该账户不再出现在记账/转账/周期选择器,账户管理页移入「已隐藏」分区。
  /// 仍计入账户余额、净资产、资产构成、净值趋势(.docs/account-archive/01 §二 D1)。
  final bool hidden;

  /// 账户图标/背景(Cloud 迁移 0041):icon_type = bank|card|custom。
  final String? iconKey;
  final String? iconType;
  final String? backgroundKey;

  /// 信用卡账单派生字段(Cloud 0022/0032):账单日在本表用 billingDay(日号)。
  final int? billStatus;
  final double? billAmountDue;
  final double? billMinimumAmount;
  final double? billPaidAmount;
  final double? billRemainingAmount;

  /// Cloud 的完整卡号(最长 23),App 老字段 cardLastFour 保留兼容。
  final String? cardNumber;
  const Account(
      {required this.id,
      required this.ledgerId,
      required this.name,
      required this.type,
      required this.currency,
      required this.initialBalance,
      this.createdAt,
      this.updatedAt,
      required this.sortOrder,
      this.creditLimit,
      this.billingDay,
      this.paymentDueDay,
      this.bankName,
      this.cardLastFour,
      this.note,
      this.syncId,
      required this.hidden,
      this.iconKey,
      this.iconType,
      this.backgroundKey,
      this.billStatus,
      this.billAmountDue,
      this.billMinimumAmount,
      this.billPaidAmount,
      this.billRemainingAmount,
      this.cardNumber});
