class Transaction extends DataClass implements Insertable<Transaction> {
  final int id;
  final int ledgerId;
  final String type;
  final double amount;
  final int? categoryId;
  final int? accountId;
  final int? toAccountId;
  final DateTime happenedAt;
  final String? note;
  final int? recurringId;
  final String? syncId;
  final String? createdByUserId;
  final String? lastEditedByUserId;
  final String? categorySyncIdOverride;
  final String? accountSyncIdOverride;
  final String? toAccountSyncIdOverride;
  final String? tagSyncIdsOverride;

  /// 不计入收支:true 时从收支统计/图表/月年汇总剔除,但仍计入账户余额、净资产、
  /// 账单列表(.docs/transaction-flags/01 §二 D1)。
  final bool excludeFromStats;

  /// 不计入预算:true 时从预算用量剔除。与 excludeFromStats 完全独立(D2)。
  final bool excludeFromBudget;

  /// v30 交易级多币种(.docs/multi-currency-ledger):交易币种(ISO 大写)。
  /// 有账户 → 恒等于账户 currency(账户内不混币);无账户 → 用户所选(L12,
  /// 默认账本本位币)。显式存让交易自包含(同步/统计不必每次 join 账户)。
  final String? currencyCode;

  /// v30:折算到账本本位币的金额快照(按记账时汇率,保存即定,不随汇率重算)。
  /// 单币种/未折算 == amount(隐含汇率 1.0)。账本维度统计读本列(?? amount),
  /// 账户维度(余额等)仍读 amount。
  final double? nativeAmount;

  /// 支出优惠(Cloud 0023):amount 为实付,优惠仅明细不冲减余额。
  final double? discountAmount;

  /// 转账手续费/优惠(Cloud 0022):金额为原币金额。
  final double? transferFeeAmount;
  final double? transferDiscountAmount;
  final String? transferFeeAccountId;
  final String? transferFeeAccountName;

  /// 退款(Cloud 0025):isRefund 0/1, refundOfSyncId 指向原单。
  final bool? isRefund;
  final String? refundOfSyncId;

  /// 组合付款(Cloud 0028):payment_splits JSON [{accountId, accountName, amount}]。
  final String? paymentSplitsJson;

  /// 消费成员(Cloud 0024):member splits JSON。
  final String? memberSplitsJson;
  final String? memberNamesCsv;

  /// 报销标记(Cloud 0035):true 时强制 exclude_from_stats/budget。
  final bool? isReimbursement;
  const Transaction(
      {required this.id,
      required this.ledgerId,
      required this.type,
      required this.amount,
      this.categoryId,
      this.accountId,
      this.toAccountId,
      required this.happenedAt,
      this.note,
      this.recurringId,
      this.syncId,
      this.createdByUserId,
      this.lastEditedByUserId,
      this.categorySyncIdOverride,
      this.accountSyncIdOverride,
      this.toAccountSyncIdOverride,
      this.tagSyncIdsOverride,
      required this.excludeFromStats,
      required this.excludeFromBudget,
      this.currencyCode,
      this.nativeAmount,
      this.discountAmount,
      this.transferFeeAmount,
      this.transferDiscountAmount,
      this.transferFeeAccountId,
      this.transferFeeAccountName,
      this.isRefund,
      this.refundOfSyncId,
      this.paymentSplitsJson,
      this.memberSplitsJson,
      this.memberNamesCsv,
      this.isReimbursement});
